package br.com.trama.model;
import br.com.trama.model.enums.StatusCotacao; import jakarta.persistence.*; import java.time.LocalDate; import java.time.LocalDateTime; import java.util.*;
@Entity @Table(name="cotacao_corporativa") public class CotacaoCorporativa { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="id_cotacao") private Long id; @Column(name="prazo_entrega",nullable=false) private LocalDate prazoEntrega; @Enumerated(EnumType.STRING) @Column(nullable=false,length=40) private StatusCotacao status; @Column(name="data_criacao",nullable=false) private LocalDateTime dataCriacao; @ManyToOne(optional=false,fetch=FetchType.LAZY) @JoinColumn(name="id_usuario",nullable=false) private Usuario empresario; @OneToMany(mappedBy="cotacao",cascade=CascadeType.ALL,orphanRemoval=true) private List<ItemCotacao> itens=new ArrayList<>(); public CotacaoCorporativa(){} public Long getId(){return id;} public LocalDate getPrazoEntrega(){return prazoEntrega;} public void setPrazoEntrega(LocalDate v){prazoEntrega=v;} public StatusCotacao getStatus(){return status;} public void setStatus(StatusCotacao v){status=v;} public LocalDateTime getDataCriacao(){return dataCriacao;} public void setDataCriacao(LocalDateTime v){dataCriacao=v;} public Usuario getEmpresario(){return empresario;} public void setEmpresario(Usuario v){empresario=v;} public List<ItemCotacao> getItens(){return itens;} public void adicionarItem(ItemCotacao i){itens.add(i);i.setCotacao(this);} }
